    - Min value (2 in Demo 3) goes left horizontal
    - Intersection is 4, paths filled with 5
    """
    H, W = len(grid), len(grid[0])
    result = [[0 for _ in range(W)] for _ in range(H)]

    cells = {v: (r, c) for r, row in enumerate(grid) for c, x in enumerate(row) if x > 0}
    if not cells:
        return result

    # Get unique values
    values = sorted(cells.keys())

    # Apply Demo 3 pattern:
    # Value at top goes down vertical
    # Value at bottom goes horizontally (left if below the top value's col, right if above?)

    top_val = min(cells, key=lambda v: cells[v][0])  # Topmost value
    rest_values = [v for v in cells if v != top_val]

    tr, tc = cells[top_val]

    # Top value goes down
    for r in range(tr, H):
        if result[r][tc] == 0:
            result[r][tc] = 5
    result[tr][tc] = top_val  # Keep top value

    # Now for rest values
    # I'll make them also extend in some direction

    for rest_val in rest_values:
        r, c = cells[rest_val]

        # Determine direction based on position relative to top_val
        if r < tr:
            # Above top value - goes down? Or up?
            rdir = "down"
        elif r == tr:
            # Same row - extends horizontal
            if c < tc:
