            rdir = "down"
            for rr in range(tr + 1, min(tr + 5, H)):
                if result[rr][c] == 0:
                    result[rr][c] = 5
        elif rdir == "left":
            for cc in range(c, -1, -1):
                if result[r][cc] == 0:
                    result[r][cc] = 5
        elif rdir == "right":
            for cc in range(c, W):
                if result[r][cc] == 0:
                    result[r][cc] = 5
        elif rdir == "horizontal":
            if c < tc:
                for cc in range(tc, c - 1, -1):  # Left until tc
